      ) {
        configuredRuntime = createConfiguredRuntime(env, capturedComposition, workerDependencies);
      }
      const tokenExchange = configuredRuntime.tokenExchange;

      const url = new URL(request.url);

      if (url.pathname !== "/token") {
        return problemResponse(404);
      }

      if (request.method !== "POST") {
        return tokenExchange(request, workerRequestContext(request));
      }

      return rateLimitedTokenExchange(request, env, tokenExchange);
    },
  };
}

async function rateLimitedTokenExchange(
  request: Request,
  env: TokenExchangeWorkerEnv,
  tokenExchange: TokenExchangeHandler,
): Promise<Response> {
  const rateLimit = await env.TOKEN_EXCHANGE_RATE_LIMIT.limit({
    key: tokenExchangeRateLimitKey(request),
  });

  if (!rateLimit.success) {
    return oauthErrorResponse(429, "temporarily_unavailable");
  }

  return tokenExchange(request, workerRequestContext(request));
}

function createConfiguredRuntime(
  env: TokenExchangeWorkerEnv,
  composition: TokenExchangeComposition,
  dependencies: TokenExchangeWorkerRuntimeDependencies,
) {
  return {
    apiBaseUrl: env.GITHUB_API_BASE_URL,
    appId: env.GITHUB_APP_ID,
    audience: env.TOKEN_BROKER_AUDIENCE,
    privateKey: env.GITHUB_APP_PRIVATE_KEY,
    tokenExchange: createGitHubAppTokenExchange(
      {
        composition,
        githubApp: {
          ...(env.GITHUB_API_BASE_URL === undefined ? {} : { apiBaseUrl: env.GITHUB_API_BASE_URL }),
          appId: env.GITHUB_APP_ID,
          privateKey: env.GITHUB_APP_PRIVATE_KEY,
        },
        subjectTokenAudience: env.TOKEN_BROKER_AUDIENCE,
      },
      dependencies,
    ),
  } as const;
}

function workerRequestContext(request: Request) {
  return {
    observe(event: TokenExchangeEvent): void {
      const record = { ...event, rayId: request.headers.get("cf-ray") };
      workerConsoleMethod(event)(record);
    },
  };
}

function workerConsoleMethod(event: TokenExchangeEvent): (event: object) => void {
  switch (event.level) {
    case "error":
      return (value) => console.error(value);
    case "info":
      return (value) => console.info(value);
    case "warn":
      return (value) => console.warn(value);
  }
}

function tokenExchangeRateLimitKey(request: Request): string {
  return (
    request.headers.get("cf-connecting-ip") ??
    request.headers.get("x-forwarded-for")?.split(",", 1)[0]?.trim() ??
    "unknown"
  );
}

import { resolve } from "node:path";

export const repositoryRoot = resolve(import.meta.dirname, "..");
export const sourceRoot = resolve(repositoryRoot, "src/cyspbot");

export const workers = ["cyspbot-token-exchange", "cyspbot-github-webhook-receiver"];

export function workerConfigPath(worker) {
  return resolve(repositoryRoot, "config/workers", `${worker}.wrangler.jsonc`);
}
import { execFileSync } from "node:child_process";
import { parseArgs } from "node:util";
import { sourceRoot, workers, workerConfigPath } from "./deploy-configuration.mjs";

const {
  values: { "deploy-only": deployOnly, "dry-run": dryRun },
} = parseArgs({
  args: process.argv.slice(2),
  options: {
    "deploy-only": {
      type: "boolean",
      default: false,
    },
    "dry-run": {
      type: "boolean",
      default: false,
    },
  },
  strict: true,
});

if (dryRun && deployOnly) {
  console.error("--dry-run and --deploy-only cannot be used together.");
  process.exit(1);
}

const wranglerEnvironment = {
  ...process.env,
  WRANGLER_WRITE_LOGS: process.env.WRANGLER_WRITE_LOGS ?? "false",
};

if (!deployOnly) {
  for (const worker of workers) {
    dryRunWorker(worker, wranglerEnvironment);
  }
}

if (dryRun) {
  process.exit(0);
}

for (const worker of workers) {
  deployWorker(worker, wranglerEnvironment);
}

function deployWorker(worker, wranglerEnvironment) {
  runWrangler(["deploy", "--strict", "--config", workerConfigPath(worker)], wranglerEnvironment);
}

function dryRunWorker(worker, wranglerEnvironment) {
  runWrangler(
    ["deploy", "--dry-run", "--strict", "--config", workerConfigPath(worker)],
    wranglerEnvironment,
  );
}

function runWrangler(wranglerArguments, wranglerEnvironment) {
  execFileSync("pnpm", ["-C", sourceRoot, "exec", "wrangler", ...wranglerArguments], {
    env: wranglerEnvironment,
    stdio: "inherit",
  });
}
