{
  "name": "github-app-token-broker-deploy",
  "version": "0.0.1",
  "private": true,
  "type": "module",
  "scripts": {
    "check": "node --run format:check && node --run lint && node --run syntax:check && node --run source-pin:check && node --run typecheck && node --run test",
    "deploy": "node --env-file-if-exists=.env scripts/deploy.mjs",
    "deploy:dry-run": "node --env-file-if-exists=.env scripts/deploy.mjs --dry-run",
    "endpoint:check": "node scripts/production-endpoint-contract.mjs",
    "format": "oxfmt . '!src/github-app-token-broker/**'",
    "format:check": "oxfmt --check . '!src/github-app-token-broker/**'",
    "lint": "oxlint --deny-warnings --report-unused-disable-directives scripts src/*.ts test/**/*.ts",
    "probe": "node --env-file-if-exists=.env scripts/token-endpoint-probe.mjs",
    "source:accepted": "node scripts/source-pin.mjs --require-accepted",
    "source:check": "pnpm -C src/github-app-token-broker run check",
    "source:install": "pnpm -C src/github-app-token-broker install --frozen-lockfile",
    "source-pin:check": "node scripts/source-pin.mjs",
    "syntax:check": "node --check scripts/*.mjs",
    "test": "node --test scripts/*.test.mjs && vitest run --config vitest.config.ts",
    "typecheck": "tsc --project tsconfig.json"
  },
  "dependencies": {
    "@github-app-token-broker/oidc-provider-github-actions": "workspace:*",
    "@github-app-token-broker/oidc-provider-google-service-account": "workspace:*",
    "@github-app-token-broker/token-issuance-policy": "workspace:*",
    "@github-app-token-broker/worker": "workspace:*"
  },
  "devDependencies": {
    "@cloudflare/vitest-pool-workers": "0.19.1",
    "@cloudflare/workers-types": "5.20260730.1",
    "@github-app-token-broker/github": "workspace:*",
    "@github-app-token-broker/oidc": "workspace:*",
    "@tsconfig/strictest": "2.0.8",
    "@types/node": "24.13.3",
    "jose": "6.2.8",
    "oxfmt": "0.61.0",
    "oxlint": "1.76.0",
    "typescript": "7.0.2",
    "vitest": "4.1.10",
    "wrangler": "4.116.0"
  },
  "engines": {
    "node": "24"
  },
  "packageManager": "pnpm@10.33.0"
}
